index 0000000..0a99607
--- /dev/null
+++ b/app/Http/Middleware/VerificaFirmaCorriere.php
@@ -0,0 +1,16 @@
+<?php
+
+namespace App\Http\Middleware;
+
+use Closure;
+use Illuminate\Http\Request;
+
+class VerificaFirmaCorriere
+{
+    public function handle(Request $request, Closure $next)
+    {
+        $attesa = hash_hmac('sha256', $request->getContent(), config('services.corriere.webhook_secret'));
+        abort_unless(hash_equals($attesa, (string) $request->header('X-Firma')), 401, 'Firma non valida');
+        return $next($request);
+    }
+}
