+<?php
+
+namespace App\Jobs;
+
+use App\Models\Contratto;
+use Illuminate\Contracts\Queue\ShouldQueue;
+use Illuminate\Foundation\Queue\Queueable;
+
+class GeneraPdfContratto implements ShouldQueue
+{
+    use Queueable;
+    public function __construct(public Contratto $contratto, public string $urlAnteprima) {}
+    public function handle(): void
+    {
+        $destinazione = storage_path("app/contratti/{$this->contratto->id}.pdf");
+        // wkhtmltopdf rende meglio di dompdf le tabelle delle condizioni
+        exec("wkhtmltopdf --quiet {$this->urlAnteprima} {$destinazione}", $uscita, $codice);
+        if ($codice !== 0) {
+            throw new \RuntimeException("wkhtmltopdf ha restituito {$codice}");
+        }
+    }
+}
