+
+// controlla che ogni migration si possa annullare e rilanciare su un database vuoto
+class MigrazioniTest extends TestCase
+{
+    public function test_le_migration_si_annullano_e_si_rilanciano(): void
+    {
+        $this->artisan('migrate:fresh')->assertSuccessful();
